using System;using System.Linq;using System.IO;using Verse;using Verse.AI;using RimWorld;using UnityEngine;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.ToList())if(w is Dialog_Leaderboard||w is Dialog_MiniGame||w is Dialog_Difficulty)w.Close();TogetherMatch.Reset();TogetherInvite.Reset();var b=(Thing)Host.State["chess"];var p=((Pawn[])Host.State["pair"])[0];var o=(Pawn)Host.State["guestR2"];p.drafter.Drafted=false;foreach(var q in new[]{p,o}){q.jobs.EndCurrentJob(JobCondition.InterruptForced);q.needs.food.CurLevelPercentage=1;q.needs.rest.CurLevelPercentage=1;q.Position=b.Position+new IntVec3(q==p?-5:-4,0,-4);q.Notify_Teleported();}var s=GameEntry.SessionFor(b);if(s!=null)GameComponent_Recreation.Current.Remove(s);GameEntry.Commit(b.TryGetComp<CompMiniGame>().Game,b,p,o,2,false);int opened=-1,start=Find.TickManager.TicksGame;Host.Watch=()=>{int t=Find.TickManager.TicksGame;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(d!=null&&opened<0)opened=t;if((opened>=0&&t-opened>150)||t-start>1500){string text="window="+(d!=null)+"\n"+string.Join("\n",new[]{p,o}.Select(q=>q+" pos="+q.Position+" seat="+q.CurJob?.targetC+" rot="+q.Rotation.AsInt+" chair="+q.Position.GetEdifice(b.Map)?.def+" job="+q.CurJobDef));File.WriteAllText(Host.Root+"/guest-pair-r2.txt",text);if(d!=null)d.windowRect.position=new Vector2(850,30);CameraJumper.TryJump(b);Find.Selector.ClearSelection();Find.Selector.Select(p);Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Original overlap reproduction: both colonist and guest approach same side, then settle at reserved seats.";}}
